// 复用原正常人口登记夹具，只核新窗口的实际preview/start/finish与人数守恒。
#define main original_population_source_cases
#include "population_military_source_test.cpp"
#undef main
#include "resident/domains/military/population_occupation.hpp"
namespace {
Integer checks=0;
void check(bool ok,const char* message){++checks;if(!ok)throw std::runtime_error(message);}
// 此处只模拟政治纯读返回；真正occupation→政治登记链由S6原组件负责，不称本例为World占领。
PoliticalRecruitmentOccupation source(Fixture& f,Integer observed){
 MilitaryOccupationFact occupation;occupation.id="military:occupation";occupation.tick=1;occupation.garrison_id="camp";occupation.to_organization_id="city";occupation.assets_applied=true;f.military.occupation_facts={occupation};
 if(!f.common.state().facts.find(occupation.id))must(f.common.append_fact({occupation.id,"military_occupation","military"}));
 if(!f.common.state().facts.find("political:pending"))must(f.common.append_fact({"political:pending","political_public_responsibilities_pending","politics"}));
 PoliticalRecruitmentOccupation proof;proof.source_identity=f.common.state().identity;proof.registration_fact_id="political:pending";proof.occupation_fact_id=occupation.id;proof.jurisdiction_id="district";proof.site_id="town";proof.garrison_id="camp";proof.controlling_organization_id="city";proof.occupation_rule={"occupation20",1,20,5000};proof.occupation_tick=1;proof.observed_tick=observed;proof.integration_until_tick=21;proof.blocked=observed<21;return proof;
}
PopulationRecruitmentOccupationRead reader(const PoliticalRecruitmentOccupation& proof){return [proof](const StableId&)->Outcome<std::optional<PoliticalRecruitmentOccupation>>{return {true,proof,{}};};}
}
int main(){try{
 Fixture f;auto request=f.request();auto prior=must(preview_population_military(f.read(),"officer",request));check(prior.terms.count==3,"disabled old profile keeps original enrollment quote");auto proof=source(f,1);auto read=f.read();read.recruitment_occupation=reader(proof);const auto original=encode_common_state(f.common.state());auto denied=preview_population_military(read,"officer",request);check(!denied.ok&&denied.error.original.code=="PopulationRecruitmentOccupationBlocked","actual preview denies integration window");check(compare_boundary(original,encode_common_state(f.common.state())).exact()&&f.economy.cohorts.find("reserve")->headcount==6&&f.military.military_units[0].fit.empty(),"blocked quote changes no Common resources or people");
 proof.source_identity.revision++;read.recruitment_occupation=reader(proof);check(!preview_population_military(read,"officer",request).ok,"other candidate identity cannot authorize window");proof=source(f,1);proof.blocked=false;read.recruitment_occupation=reader(proof);check(!preview_population_military(read,"officer",request).ok,"false blocked flag cannot bypass actual arithmetic");
 f.common.state().identity.tick=20;proof=source(f,20);read.recruitment_occupation=reader(proof);check(!validate_population_recruitment_occupation(read,*f.catalog.sources.find("source"),20).ok,"last half-day remains blocked");f.common.state().identity.tick=21;proof=source(f,21);read.recruitment_occupation=reader(proof);check(validate_population_recruitment_occupation(read,*f.catalog.sources.find("source"),21).ok,"exact integration end permits original enrollment checks");
 Fixture stale;auto quote=must(preview_population_military(stale.read(),"officer",stale.request()));ActionCoreView action;action.id=must(stale.common.next_id("action"));action.kind="population_enroll";action.actor_id="officer";action.participants={"officer"};action.start_tick=1;action.remaining_ticks=1;stale.common.state().actions.insert(action.id,action);stale.common.state().actors.find("officer")->action_id=action.id;auto write=stale.write();write.recruitment_occupation=reader(source(stale,1));auto start=start_population_military(write,action,stale.request(),quote);check(!start.ok&&stale.state.actions.empty()&&stale.military.military_units[0].mobilizing_action_id.empty(),"start requotes window and never registers stale enlistment");
 Fixture finish;auto begun=finish.start(finish.request());begun.remaining_ticks=0;auto end=finish.write();end.recruitment_occupation=reader(source(finish,2));const auto result=must(finish_population_military(end,begun));check(!result.success&&result.code=="PopulationRecruitmentOccupationBlocked"&&finish.state.enrollments.empty()&&finish.state.actions.empty()&&finish.military.military_units[0].mobilizing_action_id.empty()&&finish.economy.cohorts.find("reserve")->headcount==6&&finish.economy.cohorts.find("serving")->headcount==0,"finish loses eligibility by normal failed action and releases only own lock without people transfer");
 Fixture released;auto enrolled=released.finish(released.start(released.request()));auto release_read=released.read();release_read.recruitment_occupation=reader(source(released,released.common.tick()));PopulationReleaseCommand release{{"city","macro.office",0,"officer"},enrolled.enrollment_id,{}};check(preview_population_military(release_read,"officer",release).ok,"occupation ban does not prevent existing soldier release");
 // 对已落原typed action/fact做坏档门：即使完成时到期，开始时违规仍不可冷准入。
 Fixture cold;auto recorded=cold.finish(cold.start(cold.request()));auto historical=source(cold,1);auto context=cold.read();context.recruitment_occupation=reader(source(cold,cold.common.tick()));context.recruitment_occupation_before=[&](const StableId&,Integer tick,const StableId&)->Outcome<std::optional<PoliticalRecruitmentOccupation>>{auto proof=historical;proof.source_identity=cold.common.state().identity;proof.observed_tick=tick;proof.occupation_rule.integration_ticks=1;proof.integration_until_tick=2;proof.blocked=tick<2;return {true,proof,{}};};
 auto bad_history=validate_population_military(context);check(!bad_history.ok&&bad_history.error.original.code=="PopulationRecruitmentOccupationBlocked","cold rejects banned start even though finish reached exact expiry");
 Integer reads=0;context.recruitment_occupation_before=[&](const StableId&,Integer,const StableId&)->Outcome<std::optional<PoliticalRecruitmentOccupation>>{++reads;return {true,std::nullopt,{}};};check(validate_population_military(context).ok&&reads==2,"cold invokes original start and success completion exactly once");
 const auto* original_action=cold.state.action_facts.find(cold.state.enrollments.find(recorded.enrollment_id)->action_id);check(!validate_population_recruitment_occupation_before(context,*cold.catalog.sources.find("source"),original_action->started_tick+1,original_action->id).ok,"wrong event tick cannot borrow action boundary");
 check(!validate_population_recruitment_occupation_before(context,*cold.catalog.sources.find("source"),cold.common.tick(),"political:pending").ok,"unrelated real Common fact cannot authorize historical enrollment");
 context.recruitment_occupation_before={};check(!validate_population_military(context).ok,"enabled hot read without cold read fails closed");
 std::cout<<"POPULATION_OCCUPATION="<<checks<<" FAILURES=0 SCOPE=RECRUITMENT_CONSERVATION_COMPONENT\n";return 0;
 }catch(const std::exception& e){std::cerr<<"POPULATION_OCCUPATION_FAIL checks="<<checks<<" "<<e.what()<<'\n';return 1;}}
